package com.tregy.backend.config;
import com.github.benmanes.caffeine.cache.*;import com.tregy.backend.dto.response.ApiErrorResponse;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.http.*;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import tools.jackson.databind.json.JsonMapper;import java.io.IOException;import java.time.*;import java.util.concurrent.TimeUnit;import java.util.concurrent.atomic.AtomicInteger;
@Component public class RateLimitingFilter extends OncePerRequestFilter{
 private final Cache<String,AtomicInteger> attempts=Caffeine.newBuilder().expireAfterWrite(10,TimeUnit.MINUTES).maximumSize(10000).build();private final JsonMapper json;private final Clock clock;private final int limit;
 public RateLimitingFilter(JsonMapper json,Clock clock,@org.springframework.beans.factory.annotation.Value("${app.rate-limit.ip-requests:10}")int limit){this.json=json;this.clock=clock;this.limit=limit;}
 protected boolean shouldNotFilter(HttpServletRequest r){String p=r.getRequestURI();if(!"POST".equals(r.getMethod()))return true;return !(p.equals("/api/v1/auth/login")||p.equals("/api/v1/auth/register")||p.equals("/api/v1/auth/refresh")||p.equals("/api/v1/auth/forgot-password")||p.equals("/api/v1/auth/resend-verification")||p.equals("/api/v1/sync/events"));}
 protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String key=req.getRequestURI()+"|"+req.getRemoteAddr();int count=attempts.get(key,k->new AtomicInteger()).incrementAndGet();if(count<=limit){chain.doFilter(req,res);return;}String requestId=(String)req.getAttribute(RequestIdFilter.ATTRIBUTE);ApiErrorResponse body=new ApiErrorResponse(Instant.now(clock),429,"Too Many Requests","RATE_LIMITED","Too many requests. Try again later",req.getRequestURI(),requestId,null);res.setStatus(429);res.setHeader("Retry-After","600");res.setContentType(MediaType.APPLICATION_JSON_VALUE);json.writeValue(res.getOutputStream(),body);}
}
